package com.medicore.prescription.service; import com.medicore.prescription.dto.*; import com.medicore.prescription.entity.Prescription; import com.medicore.prescription.repository.PrescriptionRepository; import org.springframework.stereotype.Service;
@Service public class PrescriptionService {private final PrescriptionRepository repository; public PrescriptionService(PrescriptionRepository repository){this.repository=repository;} public PrescriptionResponse create(PrescriptionRequest r){return response(repository.save(new Prescription(r.userId(),r.orderId(),r.medicineId(),r.instructions())));} public PrescriptionResponse find(Long id){return response(repository.findById(id).orElseThrow(()->new IllegalArgumentException("Prescription not found")));} public PrescriptionResponse status(Long id,String status){if(!java.util.Set.of("PENDING","APPROVED","REJECTED").contains(status))throw new IllegalArgumentException("Invalid status");Prescription p=repository.findById(id).orElseThrow(()->new IllegalArgumentException("Prescription not found"));p.setStatus(status);return response(repository.save(p));} private PrescriptionResponse response(Prescription p){return new PrescriptionResponse(p.getId(),p.getUserId(),p.getOrderId(),p.getMedicineId(),p.getInstructions(),p.getStatus());}}
